  "2025 P1 Q10": {"marks":3,"subject":"Indices.","rows":[{"for":"apply \\((x^a)^b = x^{a \\times b}\\)","shows":"\\(n^6\\)"},{"for":"apply \\(x^m \\times x^n = x^{m+n}\\)","shows":"\\(n^{13}\\)"},{"for":"apply \\(\\frac{x^p}{x^q} = x^{p-q}\\)","shows":"\\(n^9\\)"}],"notes":["1. Correct answer without working — award 0/3."]},
